  const addExpense=()=>{const a=Number(expenseAmount.replace(',','.'));const projectId=expenseProjectId?Number(expenseProjectId):undefined;if(!expenseTitle.trim()||!Number.isFinite(a)||a<=0||(projectId!==undefined&&!projects.some(p=>p.id===projectId))){showAlert('معلومات ناقصة','دخل وصف المصروف ومبلغ صحيح واختار مشروعاً صالحاً إن وجد.');return;}const record:Expense={id:Date.now(),title:expenseTitle.trim(),amount:a,date:new Date().toLocaleDateString('fr-MA'),category:expenseCategory.trim()||undefined,projectId};setExpenses(v=>[record,...v]);logActivity('تسجيل مصروف',record.title+' • '+record.amount.toFixed(2)+' DH');setExpenseTitle('');setExpenseAmount('');setExpenseCategory('');setExpenseProjectId('');};
  const addQuote=()=>{const p=products.find(x=>String(x.id)===quoteProduct);const c=customers.find(x=>String(x.id)===quoteCustomer);const q=Number(quoteQty);if(!p||!c||!Number.isInteger(q)||q<1){showAlert('معلومات ناقصة','اختار المنتج والزبون والكمية.');return;}const x:Quote={id:Date.now(),productName:p.name,customerName:c.name,qty:q,unitPrice:p.price,total:q*p.price,date:new Date().toLocaleDateString('fr-MA'),status:'معلق'};setQuotes(v=>[x,...v]);setQuoteQty('1');showAlert('تم حفظ عرض السعر',`${x.total.toFixed(2)} DH`);};
  const convertQuote=(quote:Quote,type:QuoteConversionType)=>{
    let conversionQuote=quote;
    if(type==='invoice'){try{conversionQuote=applyInvoicePriceRules(quote,products);}catch(error){showAlert('ثمن الفاتورة غير صالح',error instanceof Error?error.message:'راجع أثمنة الفاتورة.');return;}}
    const stockAlreadyDeducted=documents.some(d=>d.sourceQuoteId===quote.id&&(d.type==='invoice'||d.type==='delivery'));
    const trackedQuoteLines=conversionQuote.lines?.filter(line=>line.trackStock!==false)||[];
    if((type==='invoice'||type==='delivery')&&!stockAlreadyDeducted&&trackedQuoteLines.length){
      const invalidVariantLine=trackedQuoteLines.find(line=>{
        const hasVariants=productVariants.some(v=>v.productId===line.productId);
        if(line.variantId)return !Number.isSafeInteger(line.qty)||!productVariants.some(v=>v.id===line.variantId&&v.productId===line.productId&&v.active);
        return hasVariants;
      });
      if(invalidVariantLine){showAlert('اختار النسخة','خاصك تختار نسخة صحيحة ونشطة لكل منتج عندو تنويعات قبل إصدار سند الخروج.');return;}
      const insufficient=trackedQuoteLines.find(line=>{
        if(line.variantId){const variant=productVariants.find(v=>v.id===line.variantId);return !variant||variant.stockQty<line.qty;}
        return inventoryBalanceForWarehouse(inventoryMovements,line.productId,activeWarehouseId)<line.qty;
      });
      if(insufficient){const variant=insufficient.variantId?productVariants.find(v=>v.id===insufficient.variantId):undefined;showAlert('المخزون غير كافٍ',variant?`المخزون غير كافٍ فالنسخة ${Object.values(variant.attributes).join(' / ')}. المتوفر: ${variant.stockQty}`:`الكمية المتوفرة في المخزن النشط غير كافية للمنتج ${products.find(p=>p.id===insufficient.productId)?.name||quote.productName}.`);return;}
    }
    const conversionInputQuote=(type==='invoice'||type==='delivery')&&conversionQuote.lines?.some(line=>!!line.variantId)
      ?{...conversionQuote,lines:conversionQuote.lines.map(line=>line.variantId?{...line,trackStock:false}:line)}
      :conversionQuote;
    try{
      const customer=customers.find(x=>x.name===quote.customerName);
      if(type==='invoice'&&customer?.creditLimitCentimes!==undefined){
        const currentBalance=balanceFor(customer.name)?.outstandingCentimes||0;
        if(exceedsCustomerCreditLimit(currentBalance,Math.round(conversionQuote.total*100),customer.creditLimitCentimes)){
          showAlert('تجاوز سقف الدين',`الرصيد الحالي مع الفاتورة غادي يفوت سقف الدين المحدد للزبون: ${(customer.creditLimitCentimes/100).toFixed(2)} DH.`);
          return;
        }
      }
      const result=createConvertedDocument(
        conversionInputQuote,type,documents,products,Date.now(),new Date().toLocaleDateString('fr-MA'),nextDocumentNumber(type==='invoice'?companyProfile.invoicePrefix:type==='delivery'?companyProfile.deliveryPrefix:companyProfile.proformaPrefix,documents),
      );
      const dueDate=type==='invoice'&&customer?.paymentTermsDays!==undefined
        ?calculatePaymentDueDate(new Date().toISOString(),customer.paymentTermsDays):undefined;
      const document:CommercialDocument={...result.document,...(dueDate?{dueDate}:{})};
      let nextMovements=inventoryMovements;
      const updatedProducts=result.stockDeducted?result.updatedProducts as Product[]:undefined;
      if(updatedProducts){for(const previous of products){const next=updatedProducts.find(p=>p.id===previous.id);const delta=(next?.qty??previous.qty)-previous.qty;if(delta!==0)nextMovements=appendInventoryMovement(nextMovements,{id:(type==='delivery'?'delivery-':'invoice-sale-')+result.document.id+'-'+previous.id,productId:previous.id,productName:previous.name,kind:type==='delivery'?'delivery':'sale',quantityDelta:delta,date:new Date().toISOString(),sourceId:String(result.document.id),warehouseId:activeWarehouseId});}}
      let nextVariants=productVariants;
      let nextVariantMovements=variantStockMovements;
      if((type==='invoice'||type==='delivery')&&!stockAlreadyDeducted){
        for(const [index,line] of trackedQuoteLines.entries()){
          if(!line.variantId)continue;
          const applied=applyVariantStockMovement(nextVariants,{id:'quote-delivery-'+result.document.id+'-'+index,variantId:line.variantId,kind:type==='invoice'?'sale':'delivery',quantityDelta:-line.qty,date:new Date().toISOString().slice(0,10),reference:String(result.document.id),note:(type==='invoice'?'فاتورة':'سند خروج')+' من عرض السعر '+(quote.number||quote.id)},nextVariantMovements);
          nextVariants=applied.variants;
          nextVariantMovements=[applied.movement,...nextVariantMovements];
        }
      }
      setDocuments(current=>[document,...current]);
      if(updatedProducts){setInventoryMovements(nextMovements);setProducts(updatedProducts);}
      if(nextVariants!==productVariants){setProductVariants(nextVariants);setVariantStockMovements(nextVariantMovements);}
      logActivity(type==='invoice'?'إصدار فاتورة':'إصدار سند خروج',document.number+' • '+document.customerName);
      showAlert('تم التحويل',type==='invoice'?'تسجلات الفاتورة.':'تسجل سند الخروج وتحدّث المخزون.');
    }catch(error){
      showAlert('تعذر التحويل',error instanceof Error?error.message:'وقع خطأ أثناء تحويل العرض.');
    }
  };
  const addPayment=()=>{
    const cst=customers.find(x=>String(x.id)===paymentCustomer);
    const amount=Number(paymentAmount.replace(',','.'));
    if(!cst||!Number.isFinite(amount)||amount<=0){showAlert('معلومات ناقصة','اختار الزبون ودخل مبلغ صحيح.');return;}
    const invoice=documents.find(d=>d.id===Number(paymentDocument)&&d.type==='invoice'&&d.customerName===cst.name);
    if(paymentDocument&&!invoice){showAlert('الفاتورة غير موجودة','عاود اختار فاتورة صالحة لهذا الزبون.');return;}
    const paymentId=Date.now();
    const movementDate=new Date().toISOString();
    let nextCash=cashMovements;
    let nextBank=bankMovements;
    try{
      if(paymentMethod==='نقداً'){
        nextCash=appendCashMovement(nextCash,{id:'customer-payment-cash-'+paymentId,kind:'cash_in',amountCentimes:Math.round(amount*100),date:movementDate,description:'أداء زبون: '+cst.name});
      }else if(paymentMethod==='تحويل'){
        const account=bankAccounts.find(a=>a.id===activeBankAccountId);
        if(!account)throw new Error('اختار حساباً بنكياً قبل تسجيل أداء بالتحويل.');
        nextBank=appendBankMovement(nextBank,{id:'customer-payment-bank-'+paymentId,accountId:account.id,kind:'customer_payment',amountCentimes:Math.round(amount*100),date:movementDate,description:'تحويل من الزبون: '+cst.name});
      }
      let paymentRows:Payment[];
      if(invoice){
        const result=applyPaymentToInvoice({type:'invoice',total:invoice.total,paidCentimes:invoice.paidCentimes,status:invoice.status},Math.round(amount*100));
        setDocuments(current=>current.map(d=>d.id===invoice.id?{...d,paidCentimes:result.invoice.paidCentimes,status:result.invoice.status}:d));
        paymentRows=[{id:paymentId,customerName:cst.name,amount,method:paymentMethod,date:new Date().toLocaleDateString('fr-MA'),note:paymentNote.trim(),documentId:invoice.id}];
      }else{
        const invoiceDocuments=documents.filter((document):document is CommercialDocument & {type:'invoice'}=>document.type==='invoice');const allocation=allocatePaymentAcrossInvoices(invoiceDocuments,cst.name,Math.round(amount*100));
        setDocuments(current=>current.map(document=>allocation.documents.find(updated=>updated.id===document.id)||document));
        paymentRows=allocation.allocations.map((item,index)=>{
          const target=documents.find(d=>d.id===item.documentId);
          return {id:paymentId+index,customerName:cst.name,amount:item.amountCentimes/100,method:paymentMethod,date:new Date().toLocaleDateString('fr-MA'),note:[paymentNote.trim(),target?.number||('Facture '+item.documentId)].filter(Boolean).join(' • '),documentId:item.documentId};
        });
      }
      if(paymentMethod==='نقداً')setCashMovements(nextCash);
      if(paymentMethod==='تحويل')setBankMovements(nextBank);
      setPayments(v=>[...paymentRows,...v]);logActivity('تسجيل أداء زبون',cst.name+' • '+amount.toFixed(2)+' DH');
      setPaymentAmount('');setPaymentNote('');setPaymentDocument('');
      showAlert('تم تسجيل الأداء',invoice?'تحدّث الرصيد المتبقي ديال الفاتورة.':'توزع الأداء تلقائياً على الفواتير المستحقة.');
    }catch(error){showAlert('تعذر تسجيل الأداء',error instanceof Error?error.message:'راجع مبلغ الأداء والحساب المختار.');}
  };
  const exportBackup=async()=>{try{setBackupBusy(true);const json=await createBackup({products,customers,sales,salesReturns,purchases,purchaseOrders,supplierPayments,supplierReturns,cashMovements,expenses,suppliers,quotes,payments,documents,inventoryMovements,warehouses,activeWarehouseId,bankAccounts,bankMovements,bankReconciliations,cheques,chequeEvents,productVariants,variantStockMovements,activeBankAccountId,projects,workTasks,technicians,equipment,equipmentCategories,workOrders,workTimeEntries,recurringExpenseRules,activityLog,expenseCategories,productCategories,productBrands,language,companyProfile,users,activeUserId,parkedPosCarts,contactInteractions,priceGroups,reportLayout});await Share.share({title:'HamZa backup',message:json});}catch(e){showAlert('خطأ','ما قدرناش نوجدوا النسخة الاحتياطية.');}finally{setBackupBusy(false);}};
  const importBackup=()=>{showAlert('استرجاع البيانات','هاد العملية غادي تعوض البيانات الحالية بالنسخة اللي لصقتي. واش متأكد؟',[{text:'إلغاء',style:'cancel'},{text:'استرجاع',style:'destructive',onPress:async()=>{try{setBackupBusy(true);const d=await restoreBackup(backupText);setProducts(Array.isArray(d.products)?d.products as Product[]:[]);setCustomers(Array.isArray(d.customers)?d.customers as Customer[]:[]);setSales(Array.isArray(d.sales)?d.sales as Sale[]:[]);setSalesReturns(Array.isArray(d.salesReturns)?d.salesReturns as SalesReturn[]:[]);setPurchases(Array.isArray(d.purchases)?d.purchases as Purchase[]:[]);setPurchaseOrders(Array.isArray(d.purchaseOrders)?d.purchaseOrders as PurchaseOrder[]:[]);setSupplierPayments(Array.isArray(d.supplierPayments)?d.supplierPayments as SupplierPayment[]:[]);setSupplierReturns(Array.isArray(d.supplierReturns)?d.supplierReturns as SupplierReturnRecord[]:[]);setCashMovements(Array.isArray(d.cashMovements)?d.cashMovements as CashMovement[]:[]);const restoredBankAccounts=Array.isArray(d.bankAccounts)?d.bankAccounts as BankAccount[]:[];setBankAccounts(restoredBankAccounts);setBankMovements(Array.isArray(d.bankMovements)?d.bankMovements as BankMovement[]:[]);setBankReconciliations(Array.isArray(d.bankReconciliations)?d.bankReconciliations as BankReconciliation[]:[]);setCheques(Array.isArray(d.cheques)?d.cheques as ChequeRecord[]:[]);setChequeEvents(Array.isArray(d.chequeEvents)?d.chequeEvents as ChequeEvent[]:[]);setProductVariants(normalizeProductVariants(d.productVariants));setVariantStockMovements(Array.isArray(d.variantStockMovements)?d.variantStockMovements as VariantStockMovement[]:[]);setActiveBankAccountId(typeof d.activeBankAccountId==='string'&&restoredBankAccounts.some(a=>a.id===d.activeBankAccountId)?d.activeBankAccountId:restoredBankAccounts[0]?.id||'');setExpenses(Array.isArray(d.expenses)?d.expenses as Expense[]:[]);setRecurringExpenseRules(Array.isArray(d.recurringExpenseRules)?d.recurringExpenseRules as RecurringExpenseRule[]:[]);setActivityLog(Array.isArray(d.activityLog)?(d.activityLog as ActivityEntry[]).slice(0,1000):[]);setContactInteractions(Array.isArray(d.contactInteractions)?d.contactInteractions as ContactInteraction[]:[]);setExpenseCategories(Array.isArray(d.expenseCategories)?[...new Set((d.expenseCategories as unknown[]).filter((x):x is string=>typeof x==='string'&&!!x.trim()).map(x=>x.trim()))]:DEFAULT_EXPENSE_CATEGORIES);setProductCategories(Array.isArray(d.productCategories)?(d.productCategories as unknown[]).filter((x):x is string=>typeof x==='string'&&!!x.trim()):[...new Set((Array.isArray(d.products)?(d.products as Product[]).map(p=>p.category).filter((x):x is string=>!!x):[]))]);setProductBrands(Array.isArray(d.productBrands)?(d.productBrands as unknown[]).filter((x):x is string=>typeof x==='string'&&!!x.trim()):[...new Set((Array.isArray(d.products)?(d.products as Product[]).map(p=>p.brand).filter((x):x is string=>!!x):[]))]);setSuppliers(Array.isArray(d.suppliers)?d.suppliers as Supplier[]:[]);setQuotes(Array.isArray(d.quotes)?d.quotes as Quote[]:[]);setPayments(Array.isArray(d.payments)?d.payments as Payment[]:[]);setDocuments(Array.isArray(d.documents)?d.documents as CommercialDocument[]:[]);setProjects(Array.isArray(d.projects)?d.projects as Project[]:[]);setWorkTasks(Array.isArray(d.workTasks)?d.workTasks as WorkTask[]:[]);setTechnicians(Array.isArray(d.technicians)?d.technicians as Technician[]:[]);setEquipment(Array.isArray(d.equipment)?d.equipment as Equipment[]:[]);setEquipmentCategories(normalizeEquipmentCategories(d.equipmentCategories));setWorkOrders(Array.isArray(d.workOrders)?d.workOrders as WorkOrder[]:[]);setWorkTimeEntries(Array.isArray(d.workTimeEntries)?d.workTimeEntries as WorkTimeEntry[]:[]);setCompanyProfile(normalizeCompanyProfile(d.companyProfile));const restoredWarehouses=Array.isArray(d.warehouses)?d.warehouses as Warehouse[]:[];setWarehouses(restoredWarehouses.some(w=>w.id===DEFAULT_WAREHOUSE_ID)?restoredWarehouses:[{id:DEFAULT_WAREHOUSE_ID,name:'المخزن الرئيسي',isDefault:true},...restoredWarehouses]);setActiveWarehouseId(typeof d.activeWarehouseId==='string'&&restoredWarehouses.some(w=>w.id===d.activeWarehouseId)?d.activeWarehouseId:DEFAULT_WAREHOUSE_ID);const restoredProducts=Array.isArray(d.products)?d.products as Product[]:[];const restoredMovements=Array.isArray(d.inventoryMovements)?d.inventoryMovements as InventoryMovement[]:[];setInventoryMovements([...restoredMovements,...restoredProducts.filter(p=>p.qty>0&&!restoredMovements.some(m=>m.productId===p.id)).map(p=>({id:'opening-restore-'+p.id,productId:p.id,productName:p.name,kind:'opening' as const,quantityDelta:p.qty,date:new Date().toISOString(),warehouseId:DEFAULT_WAREHOUSE_ID,note:'ترحيل رصيد منتج قديم مسترجع إلى المخزن الرئيسي'}))]);setLanguage(d.language==='FR'?'FR':'AR');setReportLayout(normalizePeriodReportLayout(d.reportLayout));setParkedPosCarts(Array.isArray(d.parkedPosCarts)?d.parkedPosCarts as ParkedPosCart[]:[]);const restoredUsers=normalizeUserAccounts(d.users,modules.map(m=>m.ar));setUsers(restoredUsers);setActiveUserId(typeof d.activeUserId==='string'&&restoredUsers.some(u=>u.id===d.activeUserId)?d.activeUserId:restoredUsers[0].id);setScreen('الرئيسية');setBackupText('');showAlert('تم الاسترجاع','ترجعات البيانات بنجاح.');}catch(e){showAlert('تعذر الاسترجاع',e instanceof Error?e.message:'النسخة غير صالحة.');}finally{setBackupBusy(false);}}}]);};
